"""Time Loop Facility Escape --- V. 2.0.1 """ 
import sys
from collections import deque

# Move index -> (char, dr, dc), listed in LEX-DESCENDING order. 
MOVES = [('W', 0, 0), ('U', -1, 0), ('R', 0, 1), ('L', 0, -1), ('D', 1, 0)]
CHARS = [m[0] for m in MOVES]
INF = 1 << 30


class Grid:
    def __init__(self, w, h, max_loops, grid):
        self.W = w; self.H = h; self.max_loops = max_loops
        self.N = w * h
        self.wall = [False] * self.N
        self.door_bit = [-1] * self.N      # door letter bit at a cell, else -1
        self.switch_bit = [-1] * self.N    # switch letter bit at a cell, else -1
        self.S = self.E = -1
        self.switch_pos = {}; self.door_pos = {}
        for r in range(h):
            for c in range(w):
                p = r * w + c; ch = grid[r][c]
                if ch == '#': self.wall[p] = True
                elif ch == 'S': self.S = p
                elif ch == 'E': self.E = p
                elif 'a' <= ch <= 'z':
                    b = ord(ch) - 97; self.switch_bit[p] = b; self.switch_pos[b] = p
                elif 'A' <= ch <= 'Z':
                    b = ord(ch) - 65; self.door_bit[p] = b; self.door_pos[b] = p
        # step[pos][mi] = neighbor reached by move mi, or -1 if wall/out-of-grid.
        # Index 0 (W) is handled by callers as "stay", so it is left as -1 here.
        self.step = [[-1] * 5 for _ in range(self.N)]
        for r in range(h):
            for c in range(w):
                p = r * w + c
                if self.wall[p]:
                    continue
                for mi, (chm, dr, dc) in enumerate(MOVES):
                    nr, nc = r + dr, c + dc
                    if 0 <= nr < h and 0 <= nc < w and not self.wall[nr * w + nc]:
                        self.step[p][mi] = nr * w + nc
        # smask[pos] = bitmask of the switch sitting on that cell (0 if none).
        self.smask = [0] * self.N
        for p in range(self.N):
            if self.switch_bit[p] >= 0:
                self.smask[p] = 1 << self.switch_bit[p]

        # Determine which doors can EVER be opened, and restrict tracking to those.
        self._compute_openable()
        # "Relevant" switches = openable switches that actually have a door.
        rel = 0
        for b in self.switch_pos:
            if (self.openable >> b) & 1 and b in self.door_pos:
                rel |= (1 << b)
        self.relevant_mask = rel
        self.rsmask = [self.smask[p] & rel for p in range(self.N)]
        self.relevant_bits = [b for b in range(26) if (rel >> b) & 1]

        # nbm[pos] = bitmask of cells reachable in one move from pos (incl. itself for
        # the W move), assuming all openable doors are open. 
        self.nbm = [0] * self.N
        for p in range(self.N):
            if self.wall[p]:
                continue
            m = 1 << p
            for mi in range(1, 5):
                np = self.step[p][mi]
                if np < 0:
                    continue
                db = self.door_bit[np]
                if db >= 0 and not (self.openable >> db) & 1:
                    continue
                m |= (1 << np)
            self.nbm[p] = m

    def _reach(self, src, odoors):
        seen = bytearray(self.N); seen[src] = 1; q = deque([src])
        while q:
            p = q.popleft()
            for mi in range(1, 5):
                np = self.step[p][mi]
                if np < 0: continue
                db = self.door_bit[np]
                if db >= 0 and not (odoors >> db) & 1: continue
                if not seen[np]:
                    seen[np] = 1; q.append(np)
        return seen

    def _compute_openable(self):
        openable = 0; changed = True
        while changed:
            changed = False
            seen = self._reach(self.S, openable)
            for b, pos in self.switch_pos.items():
                if seen[pos] and not (openable >> b) & 1 and b in self.door_pos:
                    openable |= (1 << b); changed = True
        self.openable = openable

    def bfs_dist(self, src, odoors):
        dist = [INF] * self.N; dist[src] = 0; q = deque([src])
        while q:
            p = q.popleft(); d = dist[p] + 1
            for mi in range(1, 5):
                np = self.step[p][mi]
                if np < 0: continue
                db = self.door_bit[np]
                if db >= 0 and not (odoors >> db) & 1: continue
                if dist[np] == INF:
                    dist[np] = d; q.append(np)
        return dist


class Solver:
    def __init__(self, g):
        self.g = g
        self._am_cache = {}      # (odoors, T) -> achievable_masks result
        self._feas_cache = {}    # (loops, odoors, T) -> bool
        self._dist_cache = {}    # (src, odoors) -> distance array
        self._feas_true = {}     # (loops,T) -> door-sets known feasible
        self._feas_false = {}    # (loops,T) -> door-sets known infeasible
        self._fwd_cache = {}     # (open-doors, T) -> fwd table
        self.nodes = 0

    def dist(self, src, odoors):
        k = (src, odoors)
        d = self._dist_cache.get(k)
        if d is None:
            d = self.g.bfs_dist(src, odoors)
            self._dist_cache[k] = d
        return d

    # ================= PHASE A: door-only feasibility (collisions ignored) =================
    def achievable_masks(self, odoors, T):
        key = (odoors, T)
        c = self._am_cache.get(key)
        if c is not None:
            return c
        g = self.g; rsmask = g.rsmask; step = g.step; door_bit = g.door_bit
        start = rsmask[g.S]
        cur = {g.S: [start]}          # cell -> antichain of crossed masks at this time
        collected = [start]           # global antichain over all times <= T
        for _ in range(T):
            nxt = {}
            for p, masks in cur.items():
                sp = step[p]
                for mi in range(1, 5):
                    np = sp[mi]
                    if np < 0: continue
                    db = door_bit[np]
                    if db >= 0 and not (odoors >> db) & 1: continue   # door still shut
                    sm = rsmask[np]
                    lst = nxt.get(np)
                    if lst is None:
                        lst = nxt[np] = []
                    # extend each mask by the switch on the new cell; keep antichain
                    for m in masks:
                        nm = m | sm
                        dom = False
                        for x in lst:
                            if (nm | x) == x:        # nm subset of x -> dominated
                                dom = True; break
                        if not dom:
                            lst[:] = [x for x in lst if (nm | x) != nm]  # drop subsets of nm
                            lst.append(nm)
            cur = nxt
            if not cur:
                break
            # fold this time layer into the global antichain (walk may stop any time <= T)
            for p, masks in cur.items():
                for m in masks:
                    dom = False
                    for x in collected:
                        if (m | x) == x:
                            dom = True; break
                    if not dom:
                        collected[:] = [x for x in collected if (m | x) != m]
                        collected.append(m)
        self._am_cache[key] = collected
        return collected

    def feasible(self, loops, odoors, T):
        if loops <= 0:
            return False
        g = self.g
        # If E is already reachable within T, this loop alone finishes the mission.
        if self.dist(g.S, odoors)[g.E] <= T:
            return True
        if loops == 1:
            return False
        key = (loops, odoors, T)
        v = self._feas_cache.get(key)
        if v is not None:
            return v
        # Monotone short-circuits (avoid the expensive mask DP when possible).
        lk = (loops, T)
        ft = self._feas_true.get(lk)
        if ft is not None:
            for o in ft:
                if (o & odoors) == o:        # a feasible subset is open -> feasible
                    return True
        ff = self._feas_false.get(lk)
        if ff is not None:
            for o in ff:
                if (odoors & o) == odoors:   # we are a subset of an infeasible set -> infeasible
                    return False
        # Otherwise: this loop opens some set of doors, then recurse with one fewer loop.
        masks = self.achievable_masks(odoors, T)
        nexts = {}
        for m in masks:
            no = odoors | m
            if no != odoors:
                nexts[no] = True
        res = False
        # Try the door-sets opening the most doors first (likeliest to succeed quickly).
        for no in sorted(nexts, key=lambda x: -bin(x).count('1')):
            if self.feasible(loops - 1, no, T):
                res = True; break
        self._feas_cache[key] = res
        (self._feas_true if res else self._feas_false).setdefault(lk, []).append(odoors)
        return res

    def door_optimal_T_N(self, Tcap=600):
        g = self.g
        all_doors = (1 << 26) - 1
        lo = self.dist(g.S, all_doors)[g.E]   # cannot beat the all-doors-open S->E distance
        if lo >= INF:
            return None
        ML = g.max_loops
        # Find an upper bound by doubling, then binary-search (feasibility is monotone in T).
        hi = max(lo, 1)
        if not self.feasible(ML, 0, hi):
            hi = max(hi, 2)
            while hi <= Tcap and not self.feasible(ML, 0, hi):
                hi *= 2
            if hi > Tcap:
                return None
        loT = lo
        while loT < hi:
            mid = (loT + hi) // 2
            if self.feasible(ML, 0, mid):
                hi = mid
            else:
                loT = mid + 1
        return hi

    # ================= PHASE B: collision-aware lexicographic construction =================
    def solve(self):
        g = self.g
        t0 = self.door_optimal_T_N()
        if t0 is None:
            return None
        ML = g.max_loops
        T = t0
        while True:
            for N in range(1, ML + 1):
                if not self.feasible(N, 0, T):   # cheap necessary condition (doors only)
                    continue
                self.T = T; self.N = N
                res = self._build_loops(0, 0, [])
                if res is not None:
                    return res
            T += 1
            if T > t0 + 4 * (g.W + g.H) + 50:    # safety cap; should never be hit
                return None

    def _build_loops(self, i, O, ghosts):
        g = self.g; T = self.T; N = self.N
        # Occupancy of existing ghosts at each time step (for collision checks).
        occ = [set() for _ in range(T + 1)]
        for gp in ghosts:
            for t, p in enumerate(gp):
                occ[t].add(p)

        # The final loop just has to reach E; it is built without backtracking.
        if i == N - 1:
            path = self._build_final(O, occ)
            return None if path is None else [path]

        # ----- Intermediate loop: lex DFS over moves, with two prunes -----
        rem_loops = (N - 1) - i           # loops remaining AFTER this one
        step = g.step; door_bit = g.door_bit; smask = g.smask; rsmask = g.rsmask
        cells = [pp for pp in range(g.N) if not g.wall[pp]]

        # PRUNE 1 (doors): fwd[r][pos] = Pareto-maximal sets of relevant switches that
        # a single walk from pos can still cross in <= r remaining steps (doors O).
        # fwd depends only on (open doors O, budget T) and the grid, so cache it
        # instead of rebuilding it on every recursive _build_loops call.
        fwd = self._fwd_cache.get((O, T))
        if fwd is None:
            def anti(lst, m):
                for x in lst:
                    if (m | x) == x:
                        return
                lst[:] = [x for x in lst if (m | x) != m]
                lst.append(m)
            fwd = [None] * (T + 1)
            cur = [[rsmask[pp]] if not g.wall[pp] else None for pp in range(g.N)]
            fwd[0] = cur
            for r in range(1, T + 1):
                nxt = [None] * g.N
                for pp in cells:
                    lst = [rsmask[pp]]             # option: stop here (cross only this cell)
                    spp = step[pp]
                    for mi in range(1, 5):
                        np = spp[mi]
                        if np < 0:
                            continue
                        db = door_bit[np]
                        if db >= 0 and not (O >> db) & 1:
                            continue
                        base = rsmask[pp]
                        for m in cur[np]:
                            anti(lst, base | m)     # move to np then continue from there
                    nxt[pp] = lst
                fwd[r] = nxt
                cur = nxt
            self._fwd_cache[(O, T)] = fwd

        S = g.S; E = g.E
        openable = g.openable
        static_cells = cells
        nbm = g.nbm
        Ebit = 1 << E
        notS = ~(1 << S)                            # mask that clears the S bit
        # Existing ghosts' occupancy as a per-time bitmask, for the fast reach check.
        occ_prev_mask = [0] * (T + 1)
        for tt in range(T + 1):
            mm = 0
            for c in occ[tt]:
                mm |= (1 << c)
            occ_prev_mask[tt] = mm

        # PRUNE 2 (collisions): can the FINAL robot still reach E while avoiding the
        # already-fixed ghosts AND this loop's committed partial path ?
        def reach_ok_with(posns):
            reach = Ebit
            ln = len(posns)
            for tt in range(T - 1, -1, -1):
                t1 = tt + 1
                obs = occ_prev_mask[t1]
                if t1 < ln:
                    obs |= (1 << posns[t1])
                obs &= notS
                allowed = reach & ~obs              # cells the final robot may stand on at t1
                nr = Ebit
                for pp in static_cells:
                    if nbm[pp] & allowed:           # pp can step into an allowed cell
                        nr |= (1 << pp)
                reach = nr
                if (reach >> S) & 1:     # S can already reach E -> wait at S, then go
                    return 1
            return (reach >> S) & 1

        positions = [S]                             # this loop's path so far (positions)
        path = []                                   # this loop's path so far (move indices)
        feasible = self.feasible
        result = [None]

        def dfs(t, pos, crossed):
            self.nodes += 1
            if t == T:
                # Loop finished: it becomes a ghost; recurse to build the next loops.
                ghost = positions[:]
                sub = self._build_loops(i + 1, O | crossed, ghosts + [ghost])
                if sub is not None:
                    result[0] = [self._fmt(bytes(path))] + sub
                    return True
                return False
            rem_after = T - (t + 1)
            sp = step[pos]
            occ_t1 = occ[t + 1]
            for mi in range(5):
                np = pos if mi == 0 else sp[mi]     # mi == 0 is W (stay)
                if np < 0:
                    continue
                db = door_bit[np]
                if db >= 0 and not (O >> db) & 1:
                    continue                        # closed door
                if np == E:
                    continue                        # an intermediate robot must not finish
                if np != S and np in occ_t1:
                    continue                        # would collide with a ghost (S is neutral)
                ncrossed = crossed | smask[np]
                base = O | ncrossed
                # PRUNE 1: keep this move only if some single-walk continuation from np
                # crosses enough to make the remaining loops feasible (doors only).
                good = False
                for m in fwd[rem_after][np]:
                    if feasible(rem_loops, base | m, T):
                        good = True; break
                if not good:
                    continue
                positions.append(np)
                # PRUNE 2: only meaningful when stepping onto a non-S cell, because
                # waiting at S (neutral) cannot block the final robot.
                if np == S or reach_ok_with(positions):
                    path.append(mi)
                    if dfs(t + 1, np, ncrossed):
                        return True
                    path.pop()
                positions.pop()
            return False

        return result[0] if dfs(0, S, 0) else None

    def _build_final(self, O, occ):
        g = self.g; T = self.T
        S = g.S; E = g.E; step = g.step; door_bit = g.door_bit
        # Backward DP: reach[t][pos] = True iff, starting at pos at time t, the robot
        # can be at E by time T. 
        reach = [bytearray(g.N) for _ in range(T + 1)]
        reach[T][E] = 1
        for t in range(T - 1, -1, -1):
            cur = reach[t]; nxt = reach[t + 1]
            occn = occ[t + 1]
            for pos in range(g.N):
                if g.wall[pos]:
                    continue
                if pos == E:
                    cur[pos] = 1; continue
                sp = step[pos]
                ok = 0
                for mi in range(5):
                    np = pos if mi == 0 else sp[mi]
                    if np < 0:
                        continue
                    db = door_bit[np]
                    if db >= 0 and not (O >> db) & 1:
                        continue
                    if np != S and np in occn:
                        continue
                    if nxt[np]:
                        ok = 1; break
                cur[pos] = ok
        if not reach[0][S]:
            return None
        # Greedy walk: at each step take the lex-largest move (W first) that keeps E
        # reachable in the remaining time. 
        path = []
        pos = S
        for t in range(T):
            sp = step[pos]; nxt = reach[t + 1]; occn = occ[t + 1]
            chosen = -1
            for mi in range(5):
                np = pos if mi == 0 else sp[mi]
                if np < 0:
                    continue
                db = door_bit[np]
                if db >= 0 and not (O >> db) & 1:
                    continue
                if np != S and np in occn:
                    continue
                if nxt[np]:
                    chosen = mi; pos = np; break
            if chosen < 0:
                return None
            path.append(chosen)
        return self._fmt(bytes(path))

    @staticmethod
    def _fmt(pathbytes):
        return ' '.join(CHARS[b] for b in pathbytes)


def solve_input(text):
    toks = text.split('\n')
    idx = 0
    while idx < len(toks) and toks[idx].strip() == '':
        idx += 1
    parts = toks[idx].split()
    w, h, L = int(parts[0]), int(parts[1]), int(parts[2])
    grid = toks[idx + 1: idx + 1 + h]
    # Defensive: force every row to exactly width w (pad with wall — every border is a wall).
    norm = []
    for r in range(h):
        row = grid[r] if r < len(grid) else ''
        if len(row) < w:
            row = row + '#' * (w - len(row))
        elif len(row) > w:
            row = row[:w]
        norm.append(row)
    g = Grid(w, h, L, norm)
    res = Solver(g).solve()
    return "No solution." if res is None else '\n'.join(res)


if __name__ == '__main__':
    print(solve_input(sys.stdin.read()), flush=True)

data.constraints:
- {{3}} ≤ [[width]] ≤ {{30}}
- {{3}} ≤ [[height]] ≤ {{30}}
- {{1}} ≤ [[max_loops]] ≤ {{5}}
- Every side of the grid is a wall ({{#}}).
- The grid contains exactly one {{S}} and one {{E}}.
- Each switch letter and each door letter appears at most once
- Every door is placed so that it blocks all possible routes through its location unless it is opened; it cannot be bypassed by walking around it.
- Every test case is guaranteed to have a solution.
